// src/pages/RecipesPage.jsx
import React, { useState, useEffect } from "react";
import Popover from "../components/popover/Popover";
import RecipeForm from "../components/recipes/RecipeForm";
import { auth, db } from "../firebase";
import { doc, getDoc, setDoc } from "firebase/firestore";

export default function RecipesPage() {
  const [recipes, setRecipes] = useState([]);
  const [isOpen, setIsOpen] = useState(false);
  const [editingRecipe, setEditingRecipe] = useState(null);
  const [filter, setFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [uid, setUid] = useState(null);

  // Hent innlogget bruker
  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      if (user) {
        setUid(user.uid);
      } else {
        setUid(null);
        setRecipes([]);
        setLoading(false);
      }
    });
    return unsubscribe;
  }, []);

  // Hent oppskrifter fra Firestore
  useEffect(() => {
    if (!uid) return;

    const fetchRecipes = async () => {
      try {
        const docRef = doc(db, "recipes", uid);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          setRecipes(docSnap.data().recipes || []);
        } else {
          await setDoc(docRef, { recipes: [] });
          setRecipes([]);
        }
      } catch (err) {
        console.error("Feil ved henting av recipes:", err);
        setRecipes([]);
      } finally {
        setLoading(false);
      }
    };

    fetchRecipes();
  }, [uid]);

  // Lagre oppskrifter til Firestore
  const saveRecipes = async (newRecipes) => {
    if (!uid) return;
    const docRef = doc(db, "recipes", uid);
    try {
      await setDoc(docRef, { recipes: newRecipes });
    } catch (err) {
      console.error("Feil ved lagring av recipes:", err);
    }
  };

  const handleSave = async (recipe) => {
    const newRecipes = recipes.some((r) => r.id === recipe.id)
      ? recipes.map((r) => (r.id === recipe.id ? recipe : r))
      : [...recipes, recipe];

    setRecipes(newRecipes); // Oppdater UI
    await saveRecipes(newRecipes); // Lagre i Firestore
    setIsOpen(false); // Lukk Popover
    setEditingRecipe(null);
  };

  const handleEdit = (id) => {
    const rec = recipes.find((r) => r.id === id);
    setEditingRecipe(rec);
    setIsOpen(true);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Vil du slette denne oppskriften?")) return;
    const newRecipes = recipes.filter((r) => r.id !== id);
    setRecipes(newRecipes);
    await saveRecipes(newRecipes);
  };

  if (loading) return <div>Laster oppskrifter…</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "16px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h1>Oppskrifter</h1>
        <input
          type="text"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          placeholder="Søk etter tittel eller ingrediens…"
          style={{
            padding: "8px",
            marginBottom: "16px",
            border: "1px solid #ccc",
            borderRadius: "4px",
            width: "250px",
          }}
        />
        <button
          onClick={() => {
            setEditingRecipe(null);
            setIsOpen(true);
          }}
          style={{
            background: "#4682B4",
            color: "white",
            padding: "8px 16px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          Ny oppskrift
        </button>
      </div>

      {recipes.length === 0 && (
        <p>Ingen oppskrifter enda. Klikk «Ny oppskrift» for å starte.</p>
      )}

      <div style={{ marginTop: "20px", display: "grid", gap: "16px" }}>
        {recipes
          .filter(
            (r) =>
              r.title.toLowerCase().includes(filter.toLowerCase()) ||
              (r.ingredients &&
                r.ingredients.toLowerCase().includes(filter.toLowerCase()))
          )
          .map((r) => (
            <div
              key={r.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "6px",
                padding: "16px",
                background: "#fafafa",
                display: "flex",
                justifyContent: "space-between",
                gap: "16px",
              }}
            >
              <div style={{ flex: 1 }}>
                <h2 style={{ margin: "0 0 8px 0" }}>
                  {r.title}{" "}
                  <small style={{ fontWeight: "normal", color: "#666" }}>
                    ({r.category})
                  </small>
                </h2>
                {r.time && (
                  <p>
                    <strong>Steketid:</strong> {r.time}
                  </p>
                )}
                {r.temperature && (
                  <p>
                    <strong>Grader:</strong> {r.temperature}
                  </p>
                )}
                {r.ingredients && (
                  <>
                    <strong>Ingredienser:</strong>
                    <ul>
                      {r.ingredients.split("\n").map((line, i) => (
                        <li key={i}>{line}</li>
                      ))}
                    </ul>
                  </>
                )}
                {r.instructions && (
                  <p style={{ whiteSpace: "pre-wrap" }}>
                    <strong>Fremgangsmåte:</strong>
                    <br />
                    {r.instructions}
                  </p>
                )}
                {r.image && (
                  <img
                    src={r.image}
                    alt={r.title}
                    style={{
                      maxWidth: "200px",
                      marginTop: "8px",
                      borderRadius: "4px",
                    }}
                  />
                )}
                <div style={{ display: "flex", gap: "8px", marginTop: "8px" }}>
                  <button onClick={() => handleEdit(r.id)}>Rediger</button>
                  <button
                    onClick={() => handleDelete(r.id)}
                    style={{
                      color: "white",
                      background: "#b22222",
                      border: "none",
                      padding: "4px 8px",
                    }}
                  >
                    Slett
                  </button>
                </div>
              </div>
            </div>
          ))}
      </div>

      <Popover
        open={isOpen}
        onClose={() => {
          setIsOpen(false);
          setEditingRecipe(null);
        }}
      >
        <RecipeForm
          initialData={editingRecipe}
          onSave={handleSave}
          onCancel={() => {
            setIsOpen(false);
            setEditingRecipe(null);
          }}
        />
      </Popover>
    </div>
  );
}
