const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const db = getFirestore(app);

// --- Registrering med ekstra info ---
export const registerUser = async (email, password, name, phone) => {
  try {
    // Opprett bruker i Firebase Auth
    const userCredential = await createUserWithEmailAndPassword(
      auth,
      email,
      password
    );
    const uid = userCredential.user.uid;

    // Opprett dokument i Firestore for denne brukeren
    await setDoc(doc(db, "users", uid), {
      name: name || "", // fallback hvis ikke navn er fylt inn
      phone: phone || "",
      email,
      role: "user", // alle nye brukere får "user" som default rolle
    });

    return uid;
  } catch (error) {
    alert(error.message);
    return null;
  }
};

// --- Innlogging ---
export const loginUser = async (email, password) => {
  try {
    const userCredential = await signInWithEmailAndPassword(
      auth,
      email,
      password
    );
    return userCredential.user.uid;
  } catch (error) {
    alert(error.message);
    return null;
  }
};

// --- Hent rolle for bruker ---
export const getUserRole = async () => {
  if (!auth.currentUser) return null;
  const docRef = doc(db, "users", auth.currentUser.uid);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? docSnap.data().role : null;
};

// --- Hent alle brukere (for admin) ---
export const getAllUsers = async () => {
  const querySnapshot = await getDocs(collection(db, "users"));
  return querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
};

// Hent julegaver for nåværende bruker
export const getGiftPlanner = async (uid) => {
  const docRef = doc(db, "giftPlanner", uid);
  const docSnap = await getDoc(docRef);
  if (docSnap.exists()) {
    return docSnap.data().people || [];
  }
  return [];
};

// Lagre julegaver for nåværende bruker
export const saveGiftPlanner = async (uid, people) => {
  await setDoc(doc(db, "giftPlanner", uid), { people });
};
