import { Routes, Route, Navigate } from "react-router-dom";
import { useState, useEffect } from "react";
import { auth, getUserRole } from "./firebase";

import Home from "./pages/Home";
import Game from "./pages/game/Game";
import ToDo from "./pages/ToDo";
import RecipesPage from "./pages/RecipesPage";
import GiftPlanner from "./pages/GiftPlanner";
import Layout from "./components/Layout/Layout";
import PinGate from "./components/pingate/PinGate";
import LoginPage from "./pages/LoginPage";
import AdminPage from "./pages/AdminPage";
import MinProfil from "./pages/MinProfil";

function App() {
  const [user, setUser] = useState(null);
  const [role, setRole] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (currentUser) => {
      console.log("🔥 UID som er logget inn:", currentUser?.uid);
      setUser(currentUser);
      if (currentUser) {
        const r = await getUserRole();
        console.log("🔥 Rolle funnet:", r);
        setRole(r);
      } else {
        setRole(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  if (loading) return <div>Laster...</div>; // vis kun mens vi sjekker login

  return (
    <Routes>
      {/* Login side */}
      <Route
        path="/login"
        element={user ? <Navigate to="/" /> : <LoginPage />}
      />

      {/* Admin-side */}
      <Route
        path="/admin"
        element={
          !user ? (
            <Navigate to="/login" />
          ) : role === "admin" ? (
            <Layout>
              <AdminPage />
            </Layout>
          ) : (
            <Navigate to="/" />
          )
        }
      />

      {/* Beskyttede ruter */}
      <Route
        path="/"
        element={
          user ? (
            <Layout>
              <Home />
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
      <Route
        path="/about"
        element={
          user ? (
            <Layout>
              <ToDo />
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
      <Route
        path="/contact"
        element={
          user ? (
            <Layout>
              <Game />
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
      <Route
        path="/giftPlanner"
        element={
          user ? (
            <Layout>
              <PinGate requiredPin="2412" storageKey="giftPlannerUnlocked">
                <GiftPlanner />
              </PinGate>
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
      <Route
        path="/oppskrifter"
        element={
          user ? (
            <Layout>
              <RecipesPage />
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
      <Route
        path="/minprofil"
        element={
          user ? (
            <Layout>
              <MinProfil />
            </Layout>
          ) : (
            <Navigate to="/login" />
          )
        }
      />
    </Routes>
  );
}

export default App;
