import React, { useEffect, useState } from "react";
import { auth, db } from "../firebase";
import { doc, getDoc, deleteDoc } from "firebase/firestore";
import { deleteUser } from "firebase/auth";
import { useNavigate } from "react-router-dom";

export default function MinProfil() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProfile = async () => {
      if (!auth.currentUser) return;
      try {
        const ref = doc(db, "users", auth.currentUser.uid);
        const snap = await getDoc(ref);
        if (snap.exists()) {
          setProfile(snap.data());
        }
      } catch (err) {
        console.error("Feil ved henting av profil:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleDelete = async () => {
    const confirmed = window.confirm(
      "Er du sikker på at du vil slette profilen din? Dette kan ikke angres!"
    );
    if (!confirmed) return;

    try {
      // Slett dokument i Firestore
      await deleteDoc(doc(db, "users", auth.currentUser.uid));
      // Slett Auth-bruker
      await deleteUser(auth.currentUser);
      alert("Profilen din er slettet.");
      navigate("/login"); // send til login siden
    } catch (err) {
      console.error("Feil ved sletting av profil:", err);
      alert(
        "Kunne ikke slette profilen. Du må logge inn på nytt for å slette kontoen."
      );
    }
  };

  if (loading) return <div>Laster profil…</div>;
  if (!profile) return <div>Fant ingen profilinformasjon.</div>;

  return (
    <div style={{ padding: "1rem" }}>
      <h2>Min profil</h2>
      <p>
        <strong>Navn:</strong> {profile.name}
      </p>
      <p>
        <strong>Telefon:</strong> {profile.phone}
      </p>
      <p>
        <strong>E-post:</strong> {profile.email}
      </p>
      <p>
        <strong>Rolle:</strong> {profile.role}
      </p>

      <button
        style={{
          marginTop: "1rem",
          background: "red",
          color: "white",
          padding: "0.5rem 1rem",
          border: "none",
          borderRadius: "4px",
        }}
        onClick={handleDelete}
      >
        Slett profilen min
      </button>
    </div>
  );
}
