import React from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";
import { auth } from "../../firebase";
import { signOut } from "firebase/auth";
import { useNavigate } from "react-router-dom";

export default function Navbar() {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await signOut(auth);
      navigate("/login"); // send brukeren til login-siden
    } catch (err) {
      console.error("Kunne ikke logge ut:", err);
      alert("Noe gikk galt ved utlogging.");
    }
  };

  return (
    <nav className="navbar">
      <Link to="/">Home</Link>
      <Link to="/about">ToDo</Link>
      <Link to="/contact">Game</Link>
      <Link to="/giftPlanner">Julegaver</Link>
      <Link to="/oppskrifter">Oppskrifter</Link>
      <Link to="/admin">Admin</Link>
      <Link to="/MinProfil">Min profil</Link>

      <button onClick={handleLogout} style={{ marginLeft: "1rem" }}>
        Logg ut
      </button>
    </nav>
  );
}
